'use client';

import {
  EmblorClear,
  EmblorInput,
  EmblorLabel,
  EmblorRoot,
  EmblorTag,
  EmblorTagList,
  EmblorTagRemove,
  EmblorTagText,
} from 'emblor';

type PreviewState = 'default' | 'disabled' | 'readonly' | 'invalid' | 'capacity';

export function EmblorBasicField({ previewState = 'default' }: { previewState?: PreviewState }) {
  const atCapacity = previewState === 'capacity';
  const values = atCapacity ? ['react', 'typescript', 'accessibility'] : ['react', 'typescript'];

  return (
    <EmblorRoot
      key={previewState}
      defaultValue={values}
      disabled={previewState === 'disabled'}
      readOnly={previewState === 'readonly'}
      invalid={previewState === 'invalid'}
      maxTags={atCapacity ? values.length : undefined}
      placeholderWhenFull="Maximum reached"
      className="flex w-full max-w-xl flex-col gap-2"
    >
      <EmblorLabel className="text-sm font-medium">Skills</EmblorLabel>
      <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-2 shadow-xs has-[[data-invalid]]:border-destructive has-[[data-invalid]]:ring-2 has-[[data-invalid]]:ring-destructive/20">
        <EmblorTagList className="flex flex-wrap gap-1.5">
          {(tag, index) => (
            <EmblorTag
              key={tag}
              index={index}
              className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium text-secondary-foreground"
            >
              <EmblorTagText />
              <EmblorTagRemove
                aria-label={`Remove ${tag}`}
                className="rounded-sm px-0.5 text-muted-foreground hover:bg-accent hover:text-accent-foreground"
              >
                ×
              </EmblorTagRemove>
            </EmblorTag>
          )}
        </EmblorTagList>
        <EmblorInput
          className="min-w-28 flex-1 bg-transparent text-sm outline-none disabled:cursor-not-allowed disabled:opacity-50"
          placeholder="Add a skill"
        />
        <EmblorClear className="rounded-md px-2 py-1 text-xs text-muted-foreground hover:bg-accent hover:text-accent-foreground">
          Clear
        </EmblorClear>
      </div>
      <p className="text-sm text-muted-foreground">
        {previewState === 'disabled'
          ? 'Disabled fields cannot be focused or changed.'
          : previewState === 'readonly'
            ? 'Read-only fields remain focusable but cannot be changed.'
            : previewState === 'invalid'
              ? 'The field exposes its invalid state to assistive technology.'
              : atCapacity
                ? 'The maximum of three skills has been reached.'
                : 'Press Enter to add a skill. Press Backspace to select the last tag.'}
      </p>
    </EmblorRoot>
  );
}

'use client';

import { useState } from 'react';
import {
  EmblorClear,
  EmblorInput,
  EmblorLabel,
  EmblorRoot,
  EmblorTag,
  EmblorTagList,
  EmblorTagRemove,
  EmblorTagText,
} from 'emblor';

export function EmblorControlledField() {
  const [values, setValues] = useState<string[]>(['react']);
  const [draft, setDraft] = useState('');

  return (
    <EmblorRoot
      value={values}
      onValueChange={setValues}
      inputValue={draft}
      onInputValueChange={setDraft}
      className="flex w-full max-w-xl flex-col gap-2"
    >
      <EmblorLabel className="text-sm font-medium">Controlled technologies</EmblorLabel>
      <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-2 shadow-xs">
        <EmblorTagList className="flex flex-wrap gap-1.5">
          {(tag, index) => (
            <EmblorTag
              key={tag}
              index={index}
              className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium"
            >
              <EmblorTagText />
              <EmblorTagRemove
                aria-label={`Remove ${tag}`}
                className="rounded-sm px-0.5 text-muted-foreground hover:bg-accent"
              >
                ×
              </EmblorTagRemove>
            </EmblorTag>
          )}
        </EmblorTagList>
        <EmblorInput className="min-w-28 flex-1 bg-transparent text-sm outline-none" placeholder="Add a technology" />
        <EmblorClear className="rounded-md px-2 py-1 text-xs text-muted-foreground hover:bg-accent">Clear</EmblorClear>
      </div>
      <output className="rounded-md bg-muted px-3 py-2 font-mono text-xs text-muted-foreground">
        value: {JSON.stringify(values)} · draft: {JSON.stringify(draft)}
      </output>
    </EmblorRoot>
  );
}

'use client';

import { useId, useState } from 'react';
import { EmblorInput, EmblorLabel, EmblorRoot, EmblorTag, EmblorTagList, EmblorTagRemove, EmblorTagText } from 'emblor';

export function EmblorValidationField() {
  const messageId = useId();
  const [error, setError] = useState('');

  return (
    <EmblorRoot
      defaultValue={['#react']}
      transform={(value) => value.toLowerCase()}
      validate={(value) => value.startsWith('#')}
      minLength={2}
      maxTags={4}
      invalid={Boolean(error)}
      onInputValueChange={() => setError('')}
      onValueChange={() => setError('')}
      onReject={(rejection) => setError(`“${rejection.rawValue}” must begin with #.`)}
      className="flex w-full max-w-xl flex-col gap-2"
    >
      <EmblorLabel className="text-sm font-medium">Hashtags</EmblorLabel>
      <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-2 shadow-xs has-[[data-invalid]]:border-destructive">
        <EmblorTagList className="flex flex-wrap gap-1.5">
          {(tag, index) => (
            <EmblorTag
              key={tag}
              index={index}
              className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium"
            >
              <EmblorTagText />
              <EmblorTagRemove
                aria-label={`Remove ${tag}`}
                className="rounded-sm px-0.5 text-muted-foreground hover:bg-accent"
              >
                ×
              </EmblorTagRemove>
            </EmblorTag>
          )}
        </EmblorTagList>
        <EmblorInput
          aria-describedby={messageId}
          aria-invalid={Boolean(error) || undefined}
          className="min-w-28 flex-1 bg-transparent text-sm outline-none"
          placeholder="Add #hashtag"
        />
      </div>
      <p
        id={messageId}
        aria-live="polite"
        className={error ? 'text-sm text-destructive' : 'text-sm text-muted-foreground'}
      >
        {error || 'Use a # prefix. Up to four hashtags.'}
      </p>
    </EmblorRoot>
  );
}

'use client';

import { useState } from 'react';
import { EmblorInput, EmblorLabel, EmblorRoot, EmblorTag, EmblorTagList, EmblorTagRemove, EmblorTagText } from 'emblor';

export function EmblorNativeFormField() {
  const [submitted, setSubmitted] = useState<string[]>([]);

  return (
    <form
      className="flex w-full max-w-xl flex-col gap-4"
      onSubmit={(event) => {
        event.preventDefault();
        setSubmitted(new FormData(event.currentTarget).getAll('skills[]') as string[]);
      }}
      onReset={() => setSubmitted([])}
    >
      <EmblorRoot defaultValue={['react']} name="skills[]" required className="flex flex-col gap-2">
        <EmblorLabel className="text-sm font-medium">Skills</EmblorLabel>
        <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-2 shadow-xs">
          <EmblorTagList className="flex flex-wrap gap-1.5">
            {(tag, index) => (
              <EmblorTag
                key={tag}
                index={index}
                className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium"
              >
                <EmblorTagText />
                <EmblorTagRemove
                  aria-label={`Remove ${tag}`}
                  className="rounded-sm px-0.5 text-muted-foreground hover:bg-accent"
                >
                  ×
                </EmblorTagRemove>
              </EmblorTag>
            )}
          </EmblorTagList>
          <EmblorInput className="min-w-28 flex-1 bg-transparent text-sm outline-none" placeholder="Add a skill" />
        </div>
        <p className="text-sm text-muted-foreground">Submitted as repeated skills[] values.</p>
      </EmblorRoot>
      <div className="flex flex-wrap gap-2">
        <button type="submit" className="rounded-md bg-primary px-3 py-2 text-sm font-medium text-primary-foreground">
          Read FormData
        </button>
        <button type="reset" className="rounded-md border border-input bg-background px-3 py-2 text-sm font-medium">
          Reset
        </button>
      </div>
      <output className="rounded-md bg-muted px-3 py-2 font-mono text-xs text-muted-foreground" aria-live="polite">
        {submitted.length ? JSON.stringify(submitted) : 'Submit to inspect FormData'}
      </output>
    </form>
  );
}

'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { useId, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { z } from 'zod';
import { EmblorInput, EmblorLabel, EmblorRoot, EmblorTag, EmblorTagList, EmblorTagRemove, EmblorTagText } from 'emblor';
import { Button } from '@/components/ui/button';
import { Field, FieldDescription, FieldError, FieldGroup, FieldLabel } from '@/components/ui/field';

const skillsSchema = z.object({
  skills: z.array(z.string()).min(2, 'Add at least two skills.').max(5, 'Choose no more than five skills.'),
});

type SkillsForm = z.infer<typeof skillsSchema>;

export function EmblorReactHookFormField() {
  const descriptionId = useId();
  const errorId = useId();
  const [submitted, setSubmitted] = useState<string[]>([]);
  const form = useForm<SkillsForm>({
    resolver: zodResolver(skillsSchema),
    defaultValues: { skills: ['react'] },
  });

  return (
    <form className="w-full max-w-xl" onSubmit={form.handleSubmit(({ skills }) => setSubmitted(skills))} noValidate>
      <FieldGroup className="gap-4">
        <Controller
          name="skills"
          control={form.control}
          render={({ field, fieldState }) => (
            <EmblorRoot
              value={field.value}
              onValueChange={(value) => field.onChange(value)}
              maxTags={5}
              invalid={fieldState.invalid}
            >
              <Field data-invalid={fieldState.invalid}>
                <FieldLabel asChild>
                  <EmblorLabel>Skills</EmblorLabel>
                </FieldLabel>
                <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-2 shadow-xs focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50 has-[[data-invalid]]:border-destructive has-[[data-invalid]]:ring-destructive/20">
                  <EmblorTagList className="flex flex-wrap gap-1.5">
                    {(tag, index) => (
                      <EmblorTag
                        key={tag}
                        index={index}
                        className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium"
                      >
                        <EmblorTagText />
                        <EmblorTagRemove
                          aria-label={`Remove ${tag}`}
                          className="rounded-sm px-0.5 text-muted-foreground hover:bg-accent"
                        >
                          ×
                        </EmblorTagRemove>
                      </EmblorTag>
                    )}
                  </EmblorTagList>
                  <EmblorInput
                    ref={field.ref}
                    onBlur={field.onBlur}
                    aria-describedby={`${descriptionId}${fieldState.invalid ? ` ${errorId}` : ''}`}
                    aria-invalid={fieldState.invalid}
                    className="min-w-28 flex-1 bg-transparent text-sm outline-none"
                    placeholder="Add a skill"
                  />
                </div>
                <FieldDescription id={descriptionId}>Add between two and five skills.</FieldDescription>
                {fieldState.invalid ? <FieldError id={errorId} errors={[fieldState.error]} /> : null}
              </Field>
            </EmblorRoot>
          )}
        />
        <Field orientation="horizontal" className="flex-wrap">
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              form.reset();
              setSubmitted([]);
            }}
          >
            Reset
          </Button>
          <Button type="submit">Save skills</Button>
        </Field>
        <output className="rounded-md bg-muted px-3 py-2 font-mono text-xs text-muted-foreground" aria-live="polite">
          {submitted.length ? JSON.stringify(submitted) : 'Submit to inspect the validated value'}
        </output>
      </FieldGroup>
    </form>
  );
}

