'use client';

import { useId, useState } from 'react';
import {
  EmblorInput,
  EmblorLabel,
  EmblorRoot,
  EmblorTag,
  EmblorTagList,
  EmblorTagRemove,
  EmblorTagText,
  type EmblorRejection,
} from 'emblor';

const rejectionMessages: Record<EmblorRejection['reason'], string> = {
  empty: 'Enter a value before adding it.',
  'min-length': 'That value is too short.',
  'max-length': 'That value is too long.',
  duplicate: 'That tag already exists.',
  'max-tags': 'The three-tag limit has been reached.',
  custom: 'That value is not accepted.',
};

export function EmblorConstraintsField() {
  const helpId = useId();
  const statusId = useId();
  const [tags, setTags] = useState(['react']);
  const [message, setMessage] = useState('One tag must remain.');

  return (
    <EmblorRoot
      value={tags}
      onValueChange={(value, details) => {
        setTags(value);
        setMessage(
          details.type === 'add-many'
            ? `${details.values.length} tags added from paste.`
            : details.type === 'add'
              ? `${details.value} added.`
              : details.type === 'remove'
                ? `${details.value} removed.`
                : 'Tags cleared.',
        );
      }}
      onInputValueChange={() => setMessage('One tag must remain.')}
      onReject={(rejection) => setMessage(rejectionMessages[rejection.reason])}
      minTags={1}
      maxTags={3}
      allowDuplicates={false}
      delimiters={[',', ';']}
      addOnPaste
      blurBehavior="commit"
      placeholderWhenFull="Three-tag limit reached"
      className="flex w-full max-w-xl flex-col gap-2"
    >
      <div className="flex items-center justify-between gap-3">
        <EmblorLabel className="text-sm font-medium">Project labels</EmblorLabel>
        <span className="font-mono text-xs text-muted-foreground">{tags.length}/3 tags</span>
      </div>
      <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-2 shadow-xs focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/50">
        <EmblorTagList className="flex flex-wrap gap-1.5">
          {(tag, index) => (
            <EmblorTag
              key={`${tag}-${index}`}
              index={index}
              className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium"
            >
              <EmblorTagText />
              <EmblorTagRemove
                aria-label={`Remove ${tag}`}
                className="rounded-sm px-0.5 text-muted-foreground hover:bg-accent"
              >
                ×
              </EmblorTagRemove>
            </EmblorTag>
          )}
        </EmblorTagList>
        <EmblorInput
          aria-describedby={`${helpId} ${statusId}`}
          className="min-w-36 flex-1 bg-transparent text-sm outline-none"
          placeholder="Paste comma-separated tags"
        />
      </div>
      <div className="flex flex-wrap items-start justify-between gap-2 text-sm text-muted-foreground">
        <p id={helpId}>Comma and semicolon add tags. Leaving the field commits the draft.</p>
        <output id={statusId} aria-live="polite" className="font-mono text-xs">
          {message}
        </output>
      </div>
    </EmblorRoot>
  );
}

'use client';

import { useState } from 'react';
import { Command, CommandEmpty, CommandGroup, CommandItem, CommandList } from '@/components/ui/command';
import { Popover, PopoverAnchor, PopoverContent } from '@/components/ui/popover';
import {
  EmblorClear,
  EmblorInput,
  EmblorLabel,
  EmblorRoot,
  EmblorTag,
  EmblorTagList,
  EmblorTagRemove,
  EmblorTagText,
} from 'emblor';

const suggestions = ['react', 'typescript', 'accessibility', 'design systems'];

export function EmblorSuggestionField() {
  const [tags, setTags] = useState(['react']);
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const matches = suggestions.filter(
    (suggestion) => !tags.includes(suggestion) && suggestion.includes(query.toLowerCase()),
  );

  function choose(value: string) {
    setTags((current) => [...current, value]);
    setQuery('');
    setOpen(false);
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverAnchor asChild>
        <div className="w-full max-w-xl">
          <EmblorRoot
            value={tags}
            onValueChange={setTags}
            inputValue={query}
            onInputValueChange={(value) => {
              setQuery(value);
              setOpen(true);
            }}
            className="flex flex-col gap-2"
          >
            <EmblorLabel className="text-sm font-medium">Technologies</EmblorLabel>
            <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-2 shadow-xs">
              <EmblorTagList className="flex flex-wrap gap-1.5">
                {(tag, index) => (
                  <EmblorTag
                    key={tag}
                    index={index}
                    className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium"
                  >
                    <EmblorTagText />
                    <EmblorTagRemove
                      aria-label={`Remove ${tag}`}
                      className="rounded-sm px-0.5 text-muted-foreground hover:bg-accent"
                    >
                      ×
                    </EmblorTagRemove>
                  </EmblorTag>
                )}
              </EmblorTagList>
              <EmblorInput
                className="min-w-28 flex-1 bg-transparent text-sm outline-none"
                onFocus={() => setOpen(true)}
                placeholder="Search suggestions"
              />
              <EmblorClear className="rounded-md px-2 py-1 text-xs text-muted-foreground hover:bg-accent">
                Clear
              </EmblorClear>
            </div>
          </EmblorRoot>
        </div>
      </PopoverAnchor>
      <PopoverContent className="w-[var(--radix-popover-trigger-width)] p-0" align="start" sideOffset={6}>
        <Command>
          <CommandList>
            <CommandEmpty>No matching suggestions.</CommandEmpty>
            <CommandGroup heading="Suggestions">
              {matches.map((suggestion) => (
                <CommandItem key={suggestion} value={suggestion} onSelect={() => choose(suggestion)}>
                  {suggestion}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

'use client';

import { useRef, useState } from 'react';
import SortableList, { SortableItem } from 'react-easy-sort';
import { EmblorInput, EmblorLabel, EmblorRoot, EmblorTag, EmblorTagList, EmblorTagText } from 'emblor';

type Entry = { id: string; value: string };

export function EmblorReorderField() {
  const nextId = useRef(3);
  const [entries, setEntries] = useState<Entry[]>([
    { id: 'tag-1', value: 'react' },
    { id: 'tag-2', value: 'typescript' },
  ]);

  function move(from: number, to: number) {
    if (from === to) return;
    setEntries((current) => {
      const next = [...current];
      const [entry] = next.splice(from, 1);
      next.splice(to, 0, entry);
      return next;
    });
  }

  function updateValues(values: string[]) {
    setEntries((current) =>
      values.map((value) => current.find((entry) => entry.value === value) ?? { id: `tag-${nextId.current++}`, value }),
    );
  }

  return (
    <EmblorRoot
      value={entries.map((entry) => entry.value)}
      onValueChange={updateValues}
      className="flex w-full max-w-xl flex-col gap-2"
    >
      <EmblorLabel className="text-sm font-medium">Priority technologies</EmblorLabel>
      <div className="rounded-lg border border-input bg-background p-2.5 shadow-xs">
        <EmblorTagList>
          <SortableList onSortEnd={move} className="flex flex-wrap gap-1.5">
            {entries.map((entry, index) => (
              <SortableItem key={entry.id}>
                <EmblorTag
                  as="div"
                  index={index}
                  className="inline-flex cursor-grab items-center gap-1 rounded-md bg-secondary px-2 py-1 text-sm font-medium active:cursor-grabbing"
                >
                  <span aria-hidden="true" className="text-muted-foreground">
                    ⋮⋮
                  </span>
                  <EmblorTagText />
                  <button
                    type="button"
                    aria-label={`Move ${entry.value} left`}
                    disabled={index === 0}
                    onClick={() => move(index, index - 1)}
                    className="rounded-sm px-1 text-muted-foreground disabled:opacity-30"
                  >
                    ←
                  </button>
                  <button
                    type="button"
                    aria-label={`Move ${entry.value} right`}
                    disabled={index === entries.length - 1}
                    onClick={() => move(index, index + 1)}
                    className="rounded-sm px-1 text-muted-foreground disabled:opacity-30"
                  >
                    →
                  </button>
                </EmblorTag>
              </SortableItem>
            ))}
          </SortableList>
        </EmblorTagList>
        <EmblorInput className="mt-2 w-full bg-transparent text-sm outline-none" placeholder="Add a technology" />
      </div>
      <p className="text-sm text-muted-foreground">Drag tags, or use the arrow buttons to reorder with a keyboard.</p>
    </EmblorRoot>
  );
}
